#include "native/providers/moe_accumulator/q1_moe_hawkeye_bf16_accumulator.h"
#include "native/providers/gdn/sm121_exp2_interpolated.h"
#include "native/providers/gdn/sm121_attention_rcp.h"
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <thread>
#include <vector>
namespace fs=std::filesystem;
template<class T>std::vector<T> read(const char* name,size_t count){
    std::ifstream f(name,std::ios::binary|std::ios::ate);
    if(!f||f.tellg()!=std::streamoff(count*sizeof(T)))throw std::runtime_error("input extent");
    std::vector<T> v(count);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),count*sizeof(T));
    if(!f)throw std::runtime_error("input read");return v;
}
template<class T>void write(const fs::path& name,const std::vector<T>& values){
    std::ofstream f(name,std::ios::binary);f.write(reinterpret_cast<const char*>(values.data()),values.size()*sizeof(T));
    f.close();if(!f)throw std::runtime_error("output write");
}
float rn(float v){volatile float result=v;return result;}
uint16_t bf16(float v){uint32_t b;std::memcpy(&b,&v,4);return uint16_t((b+0x7fff+((b>>16)&1))>>16);}
int main(int argc,char**argv)try{
    if(argc!=9)throw std::runtime_error("query key value exp2 rcp cache_tokens query_position output_directory");
    const unsigned cache=std::stoul(argv[6]),position=std::stoul(argv[7]),n=position+1,tiles=(n+31)/32,stride=tiles*32;
    if(!cache||cache>139264||position>=cache)throw std::runtime_error("bounded original query extent");
    const auto q=read<uint16_t>(argv[1],4096),k=read<uint16_t>(argv[2],size_t(cache)*512),v=read<uint16_t>(argv[3],size_t(cache)*512);
    const auto exp=read<unsigned char>(argv[4],qrt_sm121_exp2_interpolated::table_bytes),rcp=read<unsigned char>(argv[5],qrt_sm121_attention_rcp::table_bytes);
    if(!qrt_sm121_exp2_interpolated::valid_layout(exp.data(),exp.size())||!qrt_sm121_attention_rcp::valid_layout(rcp.data(),rcp.size()))throw std::runtime_error("table layout");
    const fs::path out(argv[8]);if(!fs::create_directory(out))throw std::runtime_error("new output directory required");
    const auto started=std::chrono::steady_clock::now();
    std::vector<float> scores(size_t(16)*stride,-INFINITY),scales(size_t(16)*tiles),denom(32),accumulator(4096),context(8192);
    std::vector<uint16_t> probability(size_t(16)*stride,0);
    std::atomic<unsigned> next{0};std::vector<std::thread> threads;
    for(unsigned worker=0;worker<4;++worker)threads.emplace_back([&]{for(;;){
        const unsigned head=next.fetch_add(1);if(head>=16)return;const unsigned kv=head/8;
        auto* score=scores.data()+size_t(head)*stride;auto* prob=probability.data()+size_t(head)*stride;
        for(unsigned key=0;key<n;++key)score[key]=rn(qrt_q1_moe_hawkeye::dot_bf16_hopper_blackwell(q.data()+head*256,k.data()+size_t(key)*512+kv*256,256)*0.0625f);
        float maximum=-INFINITY,sum_separate=1.0f,sum_fused=1.0f,acc[256]{};
        auto exponent=[&](float x){return qrt_sm121_exp2_interpolated::evaluate(exp.data(),rn(x*1.4426950408889634074f));};
        for(unsigned tile=0;tile<tiles;++tile){
            float next_max=maximum,partials[32],copy[32];
            for(unsigned lane=0;lane<32;++lane)next_max=std::fmax(next_max,score[tile*32+lane]);
            const float alpha=exponent(rn(maximum-next_max));scales[size_t(head)*tiles+tile]=alpha;
            for(unsigned lane=0;lane<32;++lane){const unsigned key=tile*32+lane;
                partials[lane]=key<n?exponent(rn(score[key]-next_max)):0.0f;prob[key]=bf16(partials[lane]);}
            for(unsigned mask:{1u,4u,2u,16u,8u}){std::copy(partials,partials+32,copy);for(unsigned lane=0;lane<32;++lane)partials[lane]=rn(copy[lane]+copy[lane^mask]);}
            sum_separate=rn(rn(sum_separate*alpha)+partials[0]);sum_fused=std::fma(sum_fused,alpha,partials[0]);maximum=next_max;
            for(unsigned column=0;column<256;++column){
                acc[column]=rn(acc[column]*alpha);
                for(unsigned begin=0;begin<32;begin+=16){uint16_t values[16];
                    for(unsigned j=0;j<16;++j){const unsigned key=tile*32+begin+j;values[j]=key<n?v[size_t(key)*512+kv*256+column]:0;}
                    acc[column]=qrt_q1_moe_hawkeye::accumulate_bf16_hopper_blackwell(acc[column],prob+tile*32+begin,values,16);
                }
            }
        }
        denom[head]=sum_separate;denom[16+head]=sum_fused;
        const float inverse_separate=qrt_sm121_attention_rcp::evaluate(rcp.data(),sum_separate),inverse_fused=qrt_sm121_attention_rcp::evaluate(rcp.data(),sum_fused);
        for(unsigned column=0;column<256;++column){const unsigned cell=head*256+column;
            accumulator[cell]=acc[column];context[cell]=rn(acc[column]*inverse_separate);context[4096+cell]=rn(acc[column]*inverse_fused);}
    }});
    for(auto& t:threads)t.join();
    for(float x:context)if(!std::isfinite(x))throw std::runtime_error("nonfinite context");
    write(out/"scores-f32.bin",scores);write(out/"probability-bf16.bin",probability);write(out/"scales-f32.bin",scales);
    write(out/"denominator-f32.bin",denom);write(out/"accumulator-f32.bin",accumulator);write(out/"context-separate-f32.bin",std::vector<float>(context.begin(),context.begin()+4096));
    write(out/"context-fused-f32.bin",std::vector<float>(context.begin()+4096,context.end()));
    std::cout<<"{\"query_position\":"<<position<<",\"cache_tokens\":"<<cache<<",\"causal_tokens\":"<<n<<",\"tile_tokens\":32,\"original_k16\":true,\"wall_seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count()<<",\"diagnostic_only\":true}\n";
    return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}
